//! A tile of blue noise: two independent channels, each a permutation of its
//! values arranged so that neighbouring texels are as unlike each other as the
//! tile allows.
//!
//! What the reflection trace offsets each pixel's sample sequence by. Against a
//! white hash the difference is where the error goes: white noise puts as much
//! of it in low frequencies as in high, so a 3x3 gather leaves blotches the size
//! of the gather; blue noise has almost none at low frequencies, so nine
//! neighbours sample the lobe evenly and the gather removes what is left.
//!
//! Generated by void and cluster (Ulichney 1993) and committed as bytes rather
//! than generated at startup: the generator is a few hundred million
//! multiply-adds, which is nothing to a test and too much for a cold start.
//! `the_committed_tile_is_what_the_generator_makes` holds the file to the
//! generator, and regenerates it under `ORRIN_UPDATE_GOLDEN=1`. Every step of
//! the generator is IEEE addition and multiplication — no `exp`, whose last
//! bit differs between platforms' maths libraries — so the bytes are the same
//! wherever it runs.

/// Texels along each side. Sixty-four, as is usual for a blue-noise tile: large
/// enough that its repeat is not visible at half resolution, small enough to
/// sit in one cache line per row of a workgroup.
pub(super) const SIDE: u32 = 64;

/// `RG8_UNORM`, row-major.
pub(super) static TILE: &[u8] = include_bytes!("../../../assets/blue_noise.bin");

#[cfg(test)]
mod tests {
    use super::*;

    const N: usize = (SIDE * SIDE) as usize;

    /// The rank of every texel in one void-and-cluster ordering.
    ///
    /// The filter is a Gaussian of sigma 1.5 texels on the torus, Ulichney's
    /// value. It is built as powers of `exp(-1 / (2 * 1.5^2))`, written out, so
    /// that the only operations are ones every platform rounds alike.
    fn ranks(seed: u64) -> Vec<u16> {
        let side = SIDE as usize;
        const Q: f64 = 0.800_737_402_916_808_1;
        let mut powers = vec![1.0f64; 2 * (side / 2) * (side / 2) + 1];
        for i in 1..powers.len() {
            powers[i] = powers[i - 1] * Q;
        }
        let kernel: Vec<f64> = (0..N)
            .map(|i| {
                let (dx, dy) = (i % side, i / side);
                let (wx, wy) = (dx.min(side - dx), dy.min(side - dy));
                powers[wx * wx + wy * wy]
            })
            .collect();

        let mut ones = vec![false; N];
        let mut energy = vec![0.0f64; N];
        let toggle = |ones: &mut [bool], energy: &mut [f64], at: usize, on: bool| {
            ones[at] = on;
            let (ax, ay) = (at % side, at / side);
            let sign = if on { 1.0 } else { -1.0 };
            for (i, e) in energy.iter_mut().enumerate() {
                let (x, y) = (i % side, i / side);
                *e += sign * kernel[((y + side - ay) % side) * side + (x + side - ax) % side];
            }
        };
        // The tightest cluster is the set texel with the most energy, the
        // largest void the unset texel with the least; ties go to the first.
        let tightest = |ones: &[bool], energy: &[f64]| {
            (0..N)
                .filter(|&i| ones[i])
                .fold(None, |best: Option<usize>, i| match best {
                    Some(b) if energy[b] >= energy[i] => Some(b),
                    _ => Some(i),
                })
                .expect("a set texel")
        };
        let largest_void = |ones: &[bool], energy: &[f64]| {
            (0..N)
                .filter(|&i| !ones[i])
                .fold(None, |best: Option<usize>, i| match best {
                    Some(b) if energy[b] <= energy[i] => Some(b),
                    _ => Some(i),
                })
                .expect("an unset texel")
        };

        // A tenth of the texels, placed by xorshift.
        let mut state = seed;
        let mut placed = 0;
        while placed < N / 10 {
            state ^= state << 13;
            state ^= state >> 7;
            state ^= state << 17;
            let at = (state % N as u64) as usize;
            if !ones[at] {
                toggle(&mut ones, &mut energy, at, true);
                placed += 1;
            }
        }
        // Move the tightest cluster into the largest void until doing so would
        // put it straight back.
        for _ in 0..N {
            let cluster = tightest(&ones, &energy);
            toggle(&mut ones, &mut energy, cluster, false);
            let void = largest_void(&ones, &energy);
            toggle(&mut ones, &mut energy, void, true);
            if void == cluster {
                break;
            }
        }

        let mut rank = vec![0u16; N];
        let (mut set, mut set_energy) = (ones.clone(), energy.clone());
        for count in (0..placed).rev() {
            let cluster = tightest(&set, &set_energy);
            toggle(&mut set, &mut set_energy, cluster, false);
            rank[cluster] = count as u16;
        }
        // Filling the largest void past half is the same as removing the
        // tightest cluster of the unset texels, because the unset texels'
        // energy is the kernel's total less the set texels'.
        for count in placed..N {
            let void = largest_void(&ones, &energy);
            toggle(&mut ones, &mut energy, void, true);
            rank[void] = count as u16;
        }
        rank
    }

    fn generate() -> Vec<u8> {
        let channels = [ranks(0x9E37_79B9_7F4A_7C15), ranks(0xD1B5_4A32_D192_ED03)];
        (0..N)
            .flat_map(|i| {
                channels
                    .iter()
                    .map(move |c| (c[i] as usize * 256 / N) as u8)
            })
            .collect()
    }

    /// The tile is generated, not authored: the file has to be exactly what
    /// the generator produces, or nobody can say how it was made. Regenerate
    /// with `ORRIN_UPDATE_GOLDEN=1 cargo test -p orrin-core --lib blue_noise`.
    #[test]
    fn the_committed_tile_is_what_the_generator_makes() {
        let made = generate();
        if std::env::var_os("ORRIN_UPDATE_GOLDEN").is_some() {
            let path =
                std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("assets/blue_noise.bin");
            std::fs::write(&path, &made).expect("failed to write the blue-noise tile");
            return;
        }
        assert!(
            TILE == made.as_slice(),
            "assets/blue_noise.bin is not what its generator makes; if the generator \
             changed on purpose, regenerate it with ORRIN_UPDATE_GOLDEN=1",
        );
    }
}
